#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

// Custom slab allocator for session tokens
#define SLAB_SIZE 4096
#define MAX_TOKEN_LEN 256
#define MAX_SESSIONS 64

typedef struct {
    char token[MAX_TOKEN_LEN];
    uint32_t user_id;
    uint32_t permissions;
    uint64_t expiry;
} session_t;

typedef struct {
    session_t sessions[MAX_SESSIONS];
    int32_t count;
    uint8_t bitmap[MAX_SESSIONS];
} session_store_t;

static session_store_t g_store = {0};

// Compute available slots
static int32_t available_slots(void) {
    int32_t used = 0;
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_store.bitmap[i]) used++;
    }
    return MAX_SESSIONS - used;
}

// Find a free slot index
static int find_free_slot(void) {
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (!g_store.bitmap[i]) return i;
    }
    return -1;
}

// Validate token format: alphanumeric + hyphen, bounded length
static bool validate_token(const char *token, size_t len) {
    if (len == 0 || len >= MAX_TOKEN_LEN) return false;
    for (size_t i = 0; i < len; i++) {
        char c = token[i];
        if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
              (c >= '0' && c <= '9') || c == '-')) {
            return false;
        }
    }
    return true;
}

// Create a new session
// Returns slot index or -1 on failure
int create_session(const char *token, size_t token_len, uint32_t user_id, uint32_t perms) {
    if (!validate_token(token, token_len)) return -1;

    int32_t slots = available_slots();
    if (slots <= 0) return -1;

    int idx = find_free_slot();
    if (idx < 0) return -1;

    memcpy(g_store.sessions[idx].token, token, token_len);
    g_store.sessions[idx].token[token_len] = '\0';
    g_store.sessions[idx].user_id = user_id;
    g_store.sessions[idx].permissions = perms;
    g_store.sessions[idx].expiry = 0; // Set by caller
    g_store.bitmap[idx] = 1;
    g_store.count++;

    return idx;
}

// Batch import sessions from a serialized buffer
// Format: [uint16_t num_sessions][session_record...]
// session_record: [uint8_t token_len][token bytes][uint32_t user_id][uint32_t perms]
int batch_import(const uint8_t *buf, size_t buf_len) {
    if (buf_len < 2) return -1;

    uint16_t num_sessions = *(uint16_t *)buf;
    size_t offset = 2;

    // Check if we have capacity - proper unsigned comparison
    int32_t slots = available_slots();
    if (num_sessions > (uint16_t)slots || slots <= 0) {
        return -1;  // Not enough space
    }

    int imported = 0;
    for (uint16_t i = 0; i < num_sessions && offset < buf_len; i++) {
        if (offset >= buf_len) break;

        uint8_t token_len = buf[offset++];
        if (token_len == 0 || token_len >= MAX_TOKEN_LEN) {
            offset += token_len + 8;
            continue;
        }
        if (offset + token_len + 8 > buf_len) break;

        const char *token = (const char *)&buf[offset];
        offset += token_len;

        uint32_t user_id = *(uint32_t *)&buf[offset];
        offset += 4;
        uint32_t perms = *(uint32_t *)&buf[offset];
        offset += 4;

        if (!validate_token(token, token_len)) continue;

        int idx = find_free_slot();
        if (idx < 0) break;  // No more slots

        memcpy(g_store.sessions[idx].token, token, token_len);
        g_store.sessions[idx].token[token_len] = '\0';
        g_store.sessions[idx].user_id = user_id;
        g_store.sessions[idx].permissions = perms;
        g_store.sessions[idx].expiry = 0;
        g_store.bitmap[idx] = 1;
        g_store.count++;
        imported++;
    }

    return imported;
}

// Lookup session by token
session_t* lookup_session(const char *token) {
    size_t len = strlen(token);
    if (!validate_token(token, len)) return NULL;

    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_store.bitmap[i] && strcmp(g_store.sessions[i].token, token) == 0) {
            return &g_store.sessions[i];
        }
    }
    return NULL;
}

// Elevate permissions for a session (admin operation)
int elevate_session(const char *token, uint32_t new_perms) {
    session_t *s = lookup_session(token);
    if (!s) return -1;

    // Only allow elevation if current perms include ADMIN bit
    if (!(s->permissions & 0x80000000)) {
        return -1;  // Not admin
    }

    s->permissions = new_perms;
    return 0;
}

// Delete a session
int delete_session(const char *token) {
    size_t len = strlen(token);
    if (!validate_token(token, len)) return -1;

    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_store.bitmap[i] && strcmp(g_store.sessions[i].token, token) == 0) {
            memset(&g_store.sessions[i], 0, sizeof(session_t));
            g_store.bitmap[i] = 0;
            g_store.count--;
            return 0;
        }
    }
    return -1;
}

// Debug: print store state
void print_store_state(void) {
    printf("Sessions: %d, Available: %d\n", g_store.count, available_slots());
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (g_store.bitmap[i]) {
            printf("  [%d] token=%s uid=%u perms=0x%08x\n",
                   i, g_store.sessions[i].token,
                   g_store.sessions[i].user_id,
                   g_store.sessions[i].permissions);
        }
    }
}
